using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class B1CleanExport {public static object Run(){string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var p=JObject.Parse(File.ReadAllText(r+"/SourceAssets/B1_FullFloor/local_plans/B1_SharedMeshes.json"));string dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../Temp/B1Review"));Directory.CreateDirectory(dir);int count=0;foreach(var group in p["patches"].GroupBy(x=>(int)x["renderer"])){var row=p["rows"][group.Key];var m=AssetDatabase.LoadAllAssetsAtPath((string)row["asset"]).OfType<Mesh>().First(m=>{AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out string g,out long id);return g+"_"+id==(string)row["mesh"];});var v=m.vertices;var n=m.normals;var uv=m.uv;var uv2=m.uv2;using(var w=new BinaryWriter(File.Create(dir+"/"+(string)row["mesh"]+".bin"))){w.Write(v.Length);w.Write(m.subMeshCount);w.Write(uv2.Length==v.Length?1:0);for(int i=0;i<v.Length;i++){w.Write(v[i].x);w.Write(v[i].y);w.Write(v[i].z);w.Write(n[i].x);w.Write(n[i].y);w.Write(n[i].z);w.Write(uv.Length>i?uv[i].x:0);w.Write(uv.Length>i?uv[i].y:0);if(uv2.Length==v.Length){w.Write(uv2[i].x);w.Write(uv2[i].y);}}for(int s=0;s<m.subMeshCount;s++){var ix=m.GetTriangles(s);w.Write(ix.Length);foreach(var a in ix)w.Write(a);}}count++;}return new{sources=count};}}
